<script lang="ts">
  import { LL, dateFormat } from "../i18n";
  import { tick } from "svelte";
  import { get } from "svelte/store";
  import { slide } from "svelte/transition";
  import { cubicOut } from "svelte/easing";
  import { Calendar, Check, ChevronRight, Clock, Copy, MessageSquare, Users } from "@lucide/svelte";

  import { formatClockTime } from "../core/transcript";
  import { countPeople, type SpeakerGroup, type VoiceSample } from "../core/speakers";
  import { peopleCountText } from "../viewer/speakerEdits";
  import {
    formatMeetingStartDay,
    formatMeetingStartWithDay,
    hasMeetingStart,
    type MeetingTimeSource,
  } from "../viewer/meetingTime";
  import { popover } from "./tags/popover";
  import PeoplePanel from "./speakers/PeoplePanel.svelte";
  import type { SpeakersSession } from "./speakers/session";
  import type { ArtifactRecordingFacts, ArtifactTimingPrecision } from "../viewer/loadArtifact";

  // When the meeting started: the instant when known, else the legacy label
  // (meetingTime.ts decides which, and in which clock).
  export let start: MeetingTimeSource | null = null;
  export let room: string | null = null;
  export let durationMs = 0;
  // The meeting's devices with any voices separated from them (groupSpeakers).
  export let speakerGroups: SpeakerGroup[] = [];
  // Present only where speakers can be changed (MeetingView decides).
  export let speakerSession: SpeakersSession | null = null;
  export let voiceSamples: ReadonlyMap<string, VoiceSample> = new Map();
  export let playingSampleId: string | null = null;
  // Whether the meeting has a summary, and what rewriting it would cost, for
  // the People panel's choice at Save (D-814).
  export let hasSummary = false;
  export let summaryCost: string | null = null;
  export let recording: ArtifactRecordingFacts | null = null;
  export let timing: ArtifactTimingPrecision | null = null;

  let open = false;
  let anchor: HTMLButtonElement;
  let panel: HTMLDivElement;

  $: dated = hasMeetingStart(start);
  // The meeting's people are the same whichever transcript is shown, so the
  // header counts what the People panel lists.
  $: people = countPeople(speakerGroups);
  $: hasAny = dated || Boolean(room) || durationMs > 0 || people.voices > 0;
  $: peopleTitle = peopleCountText(people);
  $: transcribed = formatProcessed(recording?.processedAtUtc ?? null);
  $: model = recording?.model ?? "";
  $: size = [
    recording?.words != null ? countText(recording.words, "words") : "",
    recording?.passages != null ? countText(recording.passages, "passages") : "",
  ].filter(Boolean).join(" · ");
  $: roughTiming = timing && timing.level !== "word" ? timing : null;
  $: meetingId = recording?.meetingId ?? "";
  $: hasAbout = Boolean(transcribed || model || size || roughTiming || meetingId);

  let aboutOpen = false;
  let copied = false;
  let copiedTimer: ReturnType<typeof setTimeout> | undefined;

  const PROCESSED_OPTIONS: Intl.DateTimeFormatOptions = {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  };

  function formatProcessed(iso: string | null): string {
    if (!iso) return "";
    const date = new Date(iso);
    return Number.isNaN(date.getTime()) ? "" : dateFormat(PROCESSED_OPTIONS).format(date);
  }

  function countText(n: number, what: "words" | "passages"): string {
    const t = get(LL).viewer.meeting.facts;
    return what === "words" ? t.words({ count: n }) : t.passages({ count: n });
  }

  function shortId(id: string): string {
    return id.length > 16 ? `${id.slice(0, 8)}…${id.slice(-4)}` : id;
  }

  async function copyId() {
    try {
      await navigator.clipboard.writeText(meetingId);
      copied = true;
      clearTimeout(copiedTimer);
      copiedTimer = setTimeout(() => (copied = false), 1500);
    } catch {
      copied = false;
    }
  }

  async function toggle() {
    open = !open;
    if (open) {
      await tick();
      panel?.focus({ preventScroll: true });
    }
  }
</script>

{#if hasAny}
  <button
    bind:this={anchor}
    type="button"
    class="mf-chip"
    aria-haspopup="dialog"
    aria-expanded={open}
    aria-label={$LL.viewer.meeting.facts.chip_label()}
    on:click={toggle}
  >
    {#if dated}
      <span class="mf-chip-part">
        <Calendar size={12} aria-hidden="true" />
        {formatMeetingStartDay(start)}
      </span>
    {:else if room}
      <span class="mf-chip-part min-w-0">
        <MessageSquare size={12} aria-hidden="true" />
        <span class="truncate">{room}</span>
      </span>
    {:else if durationMs > 0}
      <span class="mf-chip-part tabular-nums">
        <Clock size={12} aria-hidden="true" />
        {formatClockTime(durationMs)}
      </span>
    {/if}
    {#if people.voices > 0}
      <span class="mf-chip-part tabular-nums" title={peopleTitle}>
        <Users size={12} aria-hidden="true" />
        {people.voices}
      </span>
    {/if}
  </button>

  {#if open}
    <div
      bind:this={panel}
      use:popover={{ anchor, close: () => (open = false) }}
      class="tag-popover mf-panel"
      class:mf-wide={speakerSession !== null}
      role="dialog"
      aria-label={$LL.viewer.meeting.facts.panel_label()}
      tabindex="-1"
    >
      {#if dated || room || durationMs > 0}
        <dl class="mf-facts">
          {#if dated}
            <div class="mf-fact">
              <dt><Calendar size={14} aria-hidden="true" /><span class="sr-only">{$LL.viewer.meeting.facts.date()}</span></dt>
              <dd>{formatMeetingStartWithDay(start)}</dd>
            </div>
          {/if}
          {#if durationMs > 0}
            <div class="mf-fact">
              <dt><Clock size={14} aria-hidden="true" /><span class="sr-only">{$LL.viewer.meeting.facts.duration()}</span></dt>
              <dd class="tabular-nums">{formatClockTime(durationMs)}</dd>
            </div>
          {/if}
          {#if room}
            <div class="mf-fact">
              <dt><MessageSquare size={14} aria-hidden="true" /><span class="sr-only">{$LL.viewer.meeting.facts.room()}</span></dt>
              <dd class="truncate">{room}</dd>
            </div>
          {/if}
        </dl>
      {/if}
      {#if people.voices > 0}
        <PeoplePanel
          groups={speakerGroups}
          session={speakerSession}
          samples={voiceSamples}
          {playingSampleId}
          {hasSummary}
          {summaryCost}
          on:sample
          on:stopSample
          on:reload
        />
      {/if}
      {#if hasAbout}
        <div class="mf-about" class:open={aboutOpen}>
          <button
            type="button"
            class="mf-about-toggle"
            aria-expanded={aboutOpen}
            aria-controls="mf-about-rows"
            on:click={() => (aboutOpen = !aboutOpen)}
          >
            <span class="mf-about-label">{$LL.viewer.meeting.facts.about()}</span>
            <ChevronRight size={14} class="mf-about-caret" aria-hidden="true" />
          </button>
          {#if aboutOpen}
            <dl id="mf-about-rows" class="mf-about-rows" transition:slide={{ duration: 180, easing: cubicOut }}>
              {#if transcribed}
                <dt>{$LL.viewer.meeting.facts.transcribed()}</dt>
                <dd>{transcribed}</dd>
              {/if}
              {#if model}
                <dt>{$LL.viewer.meeting.facts.model()}</dt>
                <dd>{model}</dd>
              {/if}
              {#if size}
                <dt>{$LL.viewer.meeting.facts.size()}</dt>
                <dd class="tabular-nums">{size}</dd>
              {/if}
              {#if roughTiming}
                <dt>{$LL.viewer.meeting.facts.timing()}</dt>
                <dd title={roughTiming.detail}>{roughTiming.label}</dd>
              {/if}
              {#if meetingId}
                <dt>{$LL.viewer.meeting.facts.id()}</dt>
                <dd class="mf-id">
                  <code title={meetingId}>{shortId(meetingId)}</code>
                  <button type="button" class="mf-copy" aria-label={copied ? $LL.viewer.meeting.facts.id_copied() : $LL.viewer.meeting.facts.copy_id()} title={copied ? $LL.common.status.copied() : $LL.viewer.meeting.facts.copy_id()} on:click={copyId}>
                    {#if copied}<Check size={12} aria-hidden="true" />{:else}<Copy size={12} aria-hidden="true" />{/if}
                  </button>
                </dd>
              {/if}
            </dl>
          {/if}
        </div>
      {/if}
    </div>
  {/if}
{/if}

