<script lang="ts">
  import { createEventDispatcher, onDestroy, onMount, tick, type Snippet } from "svelte";
  import { fade } from "svelte/transition";
  import { cubicOut } from "svelte/easing";
  import { marked } from "marked";
  import DOMPurify from "dompurify";
  import {
    Play,
    Pause,
    FileText,
    ArrowLeft,
    CassetteTape,
    Pencil,
    Search,
    Trash2,
    X,
  } from "@lucide/svelte";
  import { get } from "svelte/store";

  import { LL } from "../i18n";
  import CloseButton from "./ui/CloseButton.svelte";
  import {
    formatClockTime,
    isLikelyCrosstalkAcrossBlocks,
    filterDisplaySegmentsByQuery,
    parseTimeHash,
    type JudgedDisplaySegment,
  } from "../core/transcript";
  import TranscriptWords from "./TranscriptWords.svelte";
  import ExportMenu from "./ExportMenu.svelte";
  import MeetingFacts from "./MeetingFacts.svelte";
  import SummaryRequest from "./SummaryRequest.svelte";
  import {
    describeSummaryRequestError,
    missingSummaryText,
    summaryCostLine,
    type SummaryRequestState,
    type SummaryStatus,
  } from "../viewer/meetingSummary";
  import MeetingTags from "./marking/MeetingTags.svelte";
  import TranscriptFrame from "./marking/TranscriptFrame.svelte";
  import { createMarksSession, type ApplyAnnotations, type LoadAnnotations, type MarksSession } from "./marking/session";
  import {
    createSpeakersSession,
    reloadDue,
    SPEAKER_POLL_MS,
    speakerOverlayFor,
    systemClock,
    type SpeakersClock,
  } from "./speakers/session";
  import {
    applySpeakerOverlay,
    groupSpeakers,
    type SpeakerOverlay,
    speakerOverlayFromKey,
    speakerOverlayKey,
    voiceSamples,
    withoutSplitDevices,
  } from "../core/speakers";
  import { findStops } from "../core/find";
  import { wordsByTime } from "../core/marking";
  import {
    describeAnnotationError,
    type AnnotationResult,
    type MeetingTag,
    type VocabularyTag,
  } from "../viewer/annotations";
  import { createWordHighlighter } from "../core/wordHighlight";
  import {
    keyboardEventTargetsControl,
    transcriptWordParts,
    type TranscriptWordPart,
  } from "../core/wordInteraction";
  import {
    buildTranscriptRows,
    followRowKeyForBlocks,
    type TranscriptRow,
  } from "../core/overlap";
  import {
    buildPlayheadIndex,
    resolvePlayhead,
    type PlayheadIndex,
  } from "../core/playhead";
  import type {
    DisplayTranscriptV1,
    ReadableTranscriptV1,
    TranscriptIndex,
    TranscriptSpeaker,
    TranscriptWordsV1,
  } from "../core/types";
  import type {
    ArtifactMetadata,
    ArtifactTimingPrecision,
    LoadedArtifact,
  } from "../viewer/loadArtifact";
  import type { PortableTranscriptDescriptor } from "../viewer/portable";
  import { displaySegmentsForArtifact, formatNameList, safeMeetingStem, shownSpeakerLabel, transcriptMarkdown } from "../viewer/meetingExport";
  import { loadAudioFile, saveBlob, saveTranscript } from "../viewer/exportTransfer";
  import type { MeetingCatalogEntry } from "../viewer/catalog";
  import { hasRoom, roomLabelOf } from "../viewer/rooms";
  import { withRecordedAtUtc } from "../viewer/meetingTime";
  import {
    formatInsightCreated,
    insightHeadline,
    type InsightRecord,
  } from "../viewer/insights";
  import type { DataProvider } from "../viewer/dataProvider";
  import { buildViewerHash, readViewerHash, readViewerRange, viewerUrlWithHash, type ViewerTimeRange } from "../viewer/hashRouting";
  import { eventIsInside, followScrollTop, ownsLocationHash } from "../viewer/embedHost";

  // The single-meeting reading surface (D-420 V1). It is "smart": given a
  // DataProvider and a meeting entry (or bundled mode) it loads the artifact,
  // owns playback + transcript switching, and owns the per-meeting tx/t hash
  // params. The shell owns which meeting is selected (the `meeting` prop) and
  // the meeting hash param. Extracting this makes it the standalone shareable
  // single-meeting embed (mount it directly with bundled=true).
  export let dataProvider: DataProvider;
  export let meeting: MeetingCatalogEntry | null = null;
  export let bundled = false;

  // Which surface this is mounted on (D-775). "app" is a reader inside their own
  // Nextcloud, who is the only one the operator diagnostics mean anything to.
  // "embed" is a page on the open web that has never heard of the installation
  // this recording came from. It is set by the entry point — src/public.ts
  // passes "embed" — and deliberately not by an attribute on the element: it is
  // a property of being an embed, not something an embedding page chooses.
  export let surface: "app" | "embed" = "app";
  // inSheet is true when the shell has opened this meeting as a sheet over the
  // browse list (D-654) rather than mounting it as a page of its own. It only
  // decides how leaving is offered: a close control at every width, instead of
  // the narrow-viewport-only back arrow a two-column layout needed.
  export let inSheet = false;
  // Whether this deployment can delete a meeting (D-861). The shell owns the
  // confirmation and the actual call; this header only offers the control.
  export let canDelete = false;
  export let isDesktop = false;
  export let prefersReducedMotion = false;
  // hasCatalog drives the "choose a meeting" empty-state copy (a list exists to
  // choose from) vs the bare viewer-ready copy.
  export let hasCatalog = false;
  // Shell-level "meeting id not in catalog" error (deep-link to a removed
  // meeting). Rendered in the same not-found card as an internal load failure.
  export let notFoundMessage = "";
  // Whether the shell fills the `not-found` slot for this meeting (D-885):
  // it knows why the reader cannot open it — a share waiting for them to
  // accept, or one a sharing setting refused — and says that instead of
  // "Meeting not found". A slot cannot be provided conditionally, so the
  // shell says when it has something to put there. A snippet rather than a
  // slot: this component already renders snippets, and Svelte allows one or
  // the other.
  export let notFoundFilled = false;
  export let notFound: Snippet | undefined = undefined;

  // Which insights drew on this meeting, resolved by the shell against the
  // WHOLE catalog and handed down. Empty in every build with no operator to
  // ask — a standalone export has no insights and shows no section, rather
  // than an empty one that implies there could have been some.
  export let linkedInsights: InsightRecord[] = [];
  // How many of each insight's sources this caller can read, again the shell's
  // answer: it is not meetingIds.length, because a source they may not read is
  // absent, and a count is a disclosure that it existed.
  export let insightSourceCounts: ReadonlyMap<string, number> = new Map();

  // Tags and marks (D-746), bound by the shell to the current meeting. Without a
  // loader, as in the standalone export, there is no tagging here at all.
  export let tagVocabulary: VocabularyTag[] = [];
  export let previewTags: readonly MeetingTag[] = [];
  export let loadAnnotations: LoadAnnotations | null = null;
  export let applyAnnotations: ApplyAnnotations | null = null;
  export let marksSession: MarksSession | null = null;

  const dispatch = createEventDispatcher<{
    back: void;
    enriched: MeetingCatalogEntry;
    openInsight: InsightRecord;
    tagsChanged: AnnotationResult;
    // The meeting was renamed (or, with a null title, reset to its default).
    // The shell folds a rename into its catalog; a reset needs the server's
    // default back, so the shell refetches (D-862).
    renamed: { id: string; title: string | null };
    deleteMeeting: void;
    // The audio would not play. Said out loud because the embed has no other
    // way to tell the page around it; src/public.ts re-dispatches it (D-838).
    playbackerror: string;
  }>();
  const localMarks = createMarksSession((result) => dispatch("tagsChanged", result));

  // Renaming the meeting (D-862). Offered exactly where marks can be written:
  // access to the meeting is the only gate, and the rename applies to
  // everyone's view. The write goes through the same annotations route as a
  // tag, so it sticks in the meeting file.
  let renaming = false;
  let renameDraft = "";
  let renameBusy = false;
  let renameError = "";
  let renameInputEl: HTMLInputElement | null = null;
  $: canRename = Boolean(meeting && applyAnnotations);

  function startRename() {
    renameDraft = meeting?.title ?? "";
    renameError = "";
    renaming = true;
    void tick().then(() => {
      renameInputEl?.focus();
      renameInputEl?.select();
    });
  }

  function cancelRename() {
    renaming = false;
    renameError = "";
  }

  async function submitRename(title: string) {
    if (!applyAnnotations || !meeting || renameBusy) {
      return;
    }
    renameBusy = true;
    renameError = "";
    const meetingId = meeting.id;
    try {
      await marks.setTitle(title);
      const trimmed = title.trim();
      dispatch("renamed", { id: meetingId, title: trimmed === "" ? null : trimmed });
      renaming = false;
    } catch (error) {
      renameError = describeAnnotationError(error);
    } finally {
      renameBusy = false;
    }
  }

  // Separating the voices on a shared device, and naming them. Offered only to
  // a reader in the app whose provider can both read and save speaker edits —
  // never on an embed, which is a page on the open web and changes nothing
  // (D-775) — and then only from the People list in the meeting details.
  export let speakerEditsPollMs = SPEAKER_POLL_MS;
  // The clock the time left on an apply counts down by; tests move it by hand.
  export let speakerEditsClock: SpeakersClock = systemClock;
  const speakerSession = createSpeakersSession({ pollMs: speakerEditsPollMs, clock: speakerEditsClock });
  let openedSpeakersFor: string | null = null;
  $: speakerEditsOffered =
    surface === "app" &&
    !bundled &&
    typeof dataProvider.loadSpeakerEdits === "function" &&
    typeof dataProvider.saveSpeakerEdits === "function";
  $: speakersFor = speakerEditsOffered && meeting ? meeting.id : null;
  $: if (speakersFor !== openedSpeakersFor) {
    openedSpeakersFor = speakersFor;
    void speakerSession.open(
      speakersFor ? () => dataProvider.loadSpeakerEdits!(meeting!) : null,
      speakersFor
        ? (expectRevision, doc, summary) =>
            // Keep is what no choice means, so only a rewrite is passed on:
            // a provider that predates the choice is called as it always was.
            summary === "rewrite"
              ? dataProvider.saveSpeakerEdits!(meeting!, expectRevision, doc, summary)
              : dataProvider.saveSpeakerEdits!(meeting!, expectRevision, doc)
        : null,
    );
  }
  onDestroy(() => speakerSession.close());

  // Asking for the meeting's summary (D-814): offered in the app, where an
  // operator can write one into the published meeting. While one is being
  // written the state is polled, and once it is done the meeting is read
  // again so the summary appears.
  export let summaryRequestPollMs = 5000;
  let summaryRequest: SummaryRequestState | null = null;
  let summaryRequestError = "";
  let summaryRequestFor: string | null = null;
  let summaryRequestTimer: ReturnType<typeof setTimeout> | undefined;
  // Polls in a row that failed while a summary was being written.
  let summaryRequestFailures = 0;
  const SUMMARY_REQUEST_RETRY_MAX_MS = 60_000;
  $: summaryRequestOffered =
    surface === "app" &&
    !bundled &&
    typeof dataProvider.loadSummaryRequestState === "function" &&
    typeof dataProvider.requestSummary === "function";
  $: summaryRequestKey = summaryRequestOffered && meeting ? meeting.id : null;
  $: if (summaryRequestKey !== summaryRequestFor) {
    summaryRequestFor = summaryRequestKey;
    summaryRequest = null;
    summaryRequestError = "";
    summaryRequestFailures = 0;
    clearTimeout(summaryRequestTimer);
    if (summaryRequestKey && meeting) void loadSummaryRequest(meeting);
  }
  onDestroy(() => clearTimeout(summaryRequestTimer));

  async function loadSummaryRequest(entry: MeetingCatalogEntry) {
    try {
      const next = await dataProvider.loadSummaryRequestState!(entry);
      if (meeting?.id !== entry.id) return;
      summaryRequestFailures = 0;
      takeSummaryRequest(entry, next);
    } catch (error) {
      console.error("summary request state unavailable", entry.id, error);
      if (meeting?.id !== entry.id) return;
      if (summaryRequest?.state === "writing") {
        // The summary is still being written: one lost answer must not leave
        // the page waiting for ever, so ask again, a little later each time.
        summaryRequestFailures += 1;
        clearTimeout(summaryRequestTimer);
        summaryRequestTimer = setTimeout(
          () => {
            if (meeting?.id === entry.id) void loadSummaryRequest(entry);
          },
          Math.min(summaryRequestPollMs * 2 ** summaryRequestFailures, SUMMARY_REQUEST_RETRY_MAX_MS),
        );
      } else {
        // No state means nothing is offered.
        summaryRequest = null;
      }
    }
  }

  function takeSummaryRequest(entry: MeetingCatalogEntry, next: SummaryRequestState) {
    const wasWriting = summaryRequest?.state === "writing";
    summaryRequest = next;
    clearTimeout(summaryRequestTimer);
    if (next.state === "writing") {
      summaryRequestTimer = setTimeout(() => {
        if (meeting?.id === entry.id) void loadSummaryRequest(entry);
      }, summaryRequestPollMs);
    } else if (wasWriting && next.state === "idle") {
      void reloadForSpeakers();
    }
  }

  async function askForSummary(replace: boolean) {
    const entry = meeting;
    if (!entry || !dataProvider.requestSummary) return;
    summaryRequestError = "";
    try {
      const next = await dataProvider.requestSummary(entry, replace);
      if (meeting?.id === entry.id) takeSummaryRequest(entry, next);
    } catch (error) {
      if (meeting?.id !== entry.id) return;
      summaryRequestError = describeSummaryRequestError(error);
      void loadSummaryRequest(entry);
    }
  }
  // A voice sample plays through the meeting's own player and stops itself:
  // `sampleStopMs` is where, and any other seek or pause cancels it.
  let sampleStopMs: number | null = null;
  let playingSampleId: string | null = null;
  $: marks = marksSession ?? localMarks;
  let openedMarksFor: string | null = null;
  let tabsHeight = 0;
  let searchSlot: HTMLElement | null = null;
  let overlayEl: HTMLElement | null = null;
  let playerEl: HTMLElement | null = null;
  let transcriptFrame: { remeasure: () => void } | null = null;
  let searchToggleEl: HTMLButtonElement | null = null;
  let searchOpen = false;
  let tabSwitching = false;
  let scrollHeight = 0;
  let playerHeight = 0;
  // The scroll area's scrollbar gutter, measured: it is 15px with a classic
  // scrollbar at any width, and nothing with an overlay one.
  let scrollOuterWidth = 0;
  let scrollInnerWidth = 0;
  $: scrollGutter = Math.max(0, scrollOuterWidth - scrollInnerWidth);

  type DisplaySegment = JudgedDisplaySegment;

  const CONTINUATION_GAP_MS = 60_000;


  let transcriptionStatus: LoadedArtifact["transcriptionStatus"];
  let transcriptIndex: TranscriptIndex | null = null;
  let displayTranscript: DisplayTranscriptV1 | null = null;
  let readableTranscript: ReadableTranscriptV1 | null = null;
  let summaryMarkdown: string | null = null;
  // What the summary step did, as the meeting file says (D-814).
  let summaryStatus: SummaryStatus | undefined;
  let audioSrc = "";
  // Bumped when the file at `audioSrc` was republished, to replace the player.
  let audioGeneration = 0;
  let transcriptionOnly = false;
  let captionsSrc: string | null = null;
  let chaptersSrc: string | null = null;
  let timingPrecision: ArtifactTimingPrecision | null = null;
  let artifactMetadata: ArtifactMetadata | null = null;
  // The meeting with its start completed from the file once it has loaded. A
  // single recording opened by URL (the public embed) has no catalog, so its
  // entry knows only what the file name said; the manifest's
  // meeting.recordedAtUtc is the file's own record of when it started and wins
  // over that guess. Everything that shows or exports the start reads this.
  $: meetingWithStart = withRecordedAtUtc(meeting, artifactMetadata?.recording?.recordedAtUtc ?? null);
  // Whether the PRODUCER already bounded this artifact's word ends by the
  // measured audio (manifest provenance.wordTimings.endsBoundedByAudio). When
  // it did, the legacy display-time repair must stand down: its budget would
  // clip a genuinely long word — one measured at 1.44 s against a 240 ms
  // median — back to 1 s and undo the production fix. Absent on all 197
  // already-published meetings, which is where the repair earns its keep.
  let wordEndsBoundedByAudio = false;
  let availableTranscripts: PortableTranscriptDescriptor[] = [];
  let currentTranscriptId = "";
  let defaultTranscriptId = "";
  // The transcript the meeting opened on (its default), kept across switches:
  // it says who the meeting's people are, and where each one can be heard,
  // whichever transcript is shown. The original transcript of a separated
  // meeting credits the shared device, not the voices people name.
  let openedTranscript: TranscriptWordsV1 | null = null;
  // Split devices as the file names them (LoadedArtifact.splitDevices).
  let splitDevices: TranscriptSpeaker[] = [];
  let transcriptSwitchPending = false;
  // Inline error for transcript-switch failures (e.g. SHA mismatch on an
  // alternate body). Kept separate from `errorMessage` so it shows next to the
  // switcher instead of taking over the whole "meeting failed to load" state.
  let transcriptSwitchError = "";
  let errorMessage = "";
  let audioExportBusy = false;
  let copyExportBusy = false;
  let exportStatus = "";
  let exportRequestId = 0;
  let audioRequestId = 0;
  let copyRequestId = 0;
  // lastBundled tracks the previous value of the `bundled` prop so the reactive
  // block below fires on transitions only. Initialised from the prop because
  // onMount already loads when it starts true; without that, mounting bundled
  // would load twice.
  let lastBundled = bundled;
  let loading = false;

  let currentTimeMs = 0;
  // Which turns are sounding right now, pushed by syncHighlight rather than
  // derived per frame. `activeSegments` holds the very objects
  // `displaySegments` holds, so identity comparisons downstream stay sound.
  // Word controls subscribe separately, so neither a frame nor a row change
  // invalidates every rendered word. Acoustic row evidence stays independent
  // of display alignment, which may contain rewritten or untimed prose.
  let activeSegments: DisplaySegment[] = [];
  let activeSegmentIds = new Set<string>();
  let activeFollowRowKey: string | null = null;
  let playheadIndex: PlayheadIndex<DisplaySegment> = buildPlayheadIndex<DisplaySegment>([]);
  // The stretch `activeSegments` is known to be correct across. Deliberately
  // empty to begin with, so the first call always resolves.
  let highlightValidFromMs = Number.POSITIVE_INFINITY;
  let highlightValidUntilMs = Number.NEGATIVE_INFINITY;
  const wordHighlighter = createWordHighlighter();
  let wordHighlightSource: Map<string, TranscriptWordPart[]> | null = null;
  let durationMs = 0;
  let playing = false;
  let followPlayback = true;
  let manualScrollLock = false;
  let pendingSeekMs: number | null = null;
  type MeetingTab = "summary" | "transcript";
  let activeTab: MeetingTab = "summary";
  let tabScrollTop: Record<MeetingTab, number> = { summary: 0, transcript: 0 };

  let transcriptPane: HTMLElement | null = null;
  let audioEl: HTMLAudioElement | null = null;
  let animationFrameId = 0;
  let lastAutoScrollRowKey = "";

  // The meeting-view section; used to resolve element lookups against the
  // component's ROOT NODE — the shadow root in the embedded build, the document
  // in standalone — since document.getElementById can't see shadow-tree nodes.
  let viewRootEl: HTMLElement | undefined;
  let scrollPaneEl: HTMLElement | undefined;


  // attemptedKey guards the reactive load: it is set to meeting.id BEFORE the
  // async load and is NOT cleared on failure, so a failed load does not retrigger
  // (the meeting object identity churns when the shell enriches the catalog, but
  // the id is stable). Selecting a different meeting changes the id → reload.
  let attemptedKey: string | null = null;

  function contentFadeConfig() {
    return prefersReducedMotion ? { duration: 0 } : { duration: 360 };
  }

  function playerFadeConfig() {
    // cubicOut so the card materializes early in the transition rather than
    // snapping into view near the end — pure linear opacity reads as a
    // "click" when the card bg is close to the page bg.
    return prefersReducedMotion ? { duration: 0 } : { duration: 320, easing: cubicOut };
  }

  function renderSummaryHtml(markdown: string | null): string {
    if (typeof markdown !== "string" || markdown.trim() === "") {
      return "";
    }
    const rawHtml = marked.parse(markdown, { async: false }) as string;
    return DOMPurify.sanitize(rawHtml, { USE_PROFILES: { html: true } });
  }

  // Routing is hash-only (see src/viewer/hashRouting.ts for why and the wire
  // format). These thin wrappers bind the pure helpers to the live location.
  //
  // As an embed the fragment is the host page's: its own anchors, which we
  // must neither read as ours nor rewrite (D-838). Every read goes through
  // hostHash() and every write checks ownsLocationHash, so an embed keeps its
  // transcript choice and start time to itself.
  $: ownsHash = ownsLocationHash(surface);

  function hostHash(): string {
    return ownsHash ? window.location.hash : "";
  }

  function currentViewerHash() {
    return readViewerHash(hostHash());
  }

  // A new request restores once; subsequent edits and clearing stay local.
  let selectionRequest: { range: ViewerTimeRange | null } | null = null;
  let lastSharedHash = "";
  let locationRequest = 0;
  let artifactRequest = 0;
  let urlTranscriptRequest = 0;

  function selectionHref(range: ViewerTimeRange): string {
    return viewerHref(buildViewerHash({ meeting: meeting?.id, tx: currentTranscriptId, range }));
  }

  function restoreSharedSelection() {
    if (!ownsHash) return;
    const hash = hostHash();
    lastSharedHash = hash;
    const range = readViewerRange(hash);
    selectionRequest = { range };
    if (range) {
      transcriptQuery = "";
      onlyMatching = false;
      activeTab = "transcript";
      audioEl?.pause();
      playing = false;
      seekTo(range.startMs);
    }
  }

  async function handleSharedLocation() {
    const request = ++locationRequest;
    await tick();
    if (!ownsHash || loading || hostHash() === lastSharedHash) return;
    const current = currentViewerHash();
    if (!bundled && current.meeting !== meeting?.id) return;
    if (meeting) await maybeApplyUrlTranscript(meeting);
    if (request !== locationRequest) return;
    restoreSharedSelection();
    if (!readViewerRange(hostHash())) {
      const time = parseTimeHash(hostHash());
      if (time !== null) {
        activeTab = "transcript";
        seekTo(time);
      }
    }
  }

  function viewerHref(hash: string): string {
    return viewerUrlWithHash(window.location.href, hash);
  }

  function applyArtifact(artifact: LoadedArtifact) {
    exportRequestId += 1;
    audioRequestId += 1;
    copyRequestId += 1;
    audioExportBusy = false;
    copyExportBusy = false;
    exportStatus = "";
    stopPlaybackClock();
    audioEl?.pause();
    playing = false;
    currentTimeMs = 0;
    transcriptIndex = artifact.index;
    openedTranscript = artifact.transcript;
    splitDevices = artifact.splitDevices ?? [];
    transcriptionStatus = artifact.transcriptionStatus;
    displayTranscript = artifact.displayTranscript;
    readableTranscript = artifact.readableTranscript;
    summaryMarkdown = artifact.summary;
    summaryStatus = artifact.summaryStatus;
    audioSrc = artifact.audioSrc;
    transcriptionOnly = artifact.transcriptionOnly === true;
    captionsSrc = artifact.captionsSrc;
    chaptersSrc = artifact.chaptersSrc;
    timingPrecision = artifact.timingPrecision;
    artifactMetadata = artifact.metadata;
    wordEndsBoundedByAudio = artifact.wordEndsBoundedByAudio;
    availableTranscripts = artifact.availableTranscripts;
    currentTranscriptId = artifact.currentTranscriptId;
    defaultTranscriptId =
      artifact.availableTranscripts.find((entry) => entry.isDefault)?.id ?? artifact.currentTranscriptId;
    durationMs = artifact.index.transcript.media.durationMs;
    errorMessage = "";
    manualScrollLock = false;
    lastAutoScrollRowKey = "";
    speakerSession.showing(artifact.speakerEditsRevision ?? 0, artifact.speakerSummarySha256 ?? "");
  }

  function applySwitchedTranscript(artifact: LoadedArtifact) {
    // Audio is not paused during a switch — it keeps playing through the
    // ~100-300ms rebuild. We deliberately do NOT touch audioEl.currentTime
    // here: writing back a value captured before the await would rewind
    // playback by the duration of the switch (audible stutter). The
    // requestAnimationFrame loop already keeps `currentTimeMs` synced with
    // `audioEl.currentTime`, so the transcript highlight tracks correctly
    // as soon as the new index renders.
    transcriptIndex = artifact.index;
    transcriptionStatus = artifact.transcriptionStatus;
    displayTranscript = artifact.displayTranscript;
    readableTranscript = artifact.readableTranscript;
    timingPrecision = artifact.timingPrecision;
    artifactMetadata = artifact.metadata;
    wordEndsBoundedByAudio = artifact.wordEndsBoundedByAudio;
    availableTranscripts = artifact.availableTranscripts;
    currentTranscriptId = artifact.currentTranscriptId;
    lastAutoScrollRowKey = "";
  }

  function resetLoadedArtifact() {
    selectionRequest = null;
    locationRequest += 1;
    artifactRequest += 1;
    urlTranscriptRequest += 1;
    exportRequestId += 1;
    audioRequestId += 1;
    copyRequestId += 1;
    audioExportBusy = false;
    copyExportBusy = false;
    exportStatus = "";
    stopPlaybackClock();
    audioEl?.pause();
    playing = false;
    currentTimeMs = 0;
    transcriptIndex = null;
    transcriptionStatus = undefined;
    displayTranscript = null;
    readableTranscript = null;
    summaryMarkdown = null;
    summaryStatus = undefined;
    audioSrc = "";
    transcriptionOnly = false;
    captionsSrc = null;
    chaptersSrc = null;
    timingPrecision = null;
    artifactMetadata = null;
    wordEndsBoundedByAudio = false;
    availableTranscripts = [];
    currentTranscriptId = "";
    defaultTranscriptId = "";
    openedTranscript = null;
    splitDevices = [];
    transcriptSwitchPending = false;
    transcriptSwitchError = "";
    durationMs = 0;
    manualScrollLock = false;
    lastAutoScrollRowKey = "";
    speakerSession.showing(null);
  }

  function exportStem(): string {
    return safeMeetingStem(meeting ?? { title: "Meeting", id: "transcript" });
  }

  async function copyTranscript() {
    if (copyExportBusy) return;
    const text = transcriptMarkdown(meetingWithStart, displaySegments);
    if (!navigator.clipboard?.writeText) {
      exportStatus = get(LL).viewer.meeting.view.export_clipboard_unavailable();
      return;
    }
    const requestId = ++exportRequestId;
    const copyId = ++copyRequestId;
    copyExportBusy = true;
    try {
      await navigator.clipboard.writeText(text);
      if (requestId === exportRequestId) exportStatus = get(LL).viewer.meeting.view.export_copied();
    } catch {
      if (requestId === exportRequestId) exportStatus = get(LL).viewer.meeting.view.export_clipboard_blocked();
    } finally {
      if (copyId === copyRequestId) copyExportBusy = false;
    }
  }

  function downloadTranscript() {
    exportRequestId += 1;
    saveTranscript(transcriptMarkdown(meetingWithStart, displaySegments), `${exportStem()}-transcript.md`);
    exportStatus = get(LL).viewer.meeting.view.export_downloaded();
  }

  function downloadSummary() {
    if (!summaryMarkdown?.trim()) return;
    exportRequestId += 1;
    saveTranscript(summaryMarkdown, `${exportStem()}-summary.md`);
    exportStatus = get(LL).viewer.meeting.view.export_summary_downloaded();
  }

  async function downloadAudio() {
    if (!(meeting?.meetingPath ?? audioSrc) || audioExportBusy) return;
    const requestId = ++exportRequestId;
    const audioId = ++audioRequestId;
    const source = meeting?.meetingPath ?? audioSrc;
    audioExportBusy = true;
    exportStatus = get(LL).viewer.meeting.view.export_preparing_file();
    try {
      const file = await loadAudioFile({
        id: meeting?.id ?? "meeting",
        title: meeting?.title ?? "Meeting",
        audioPath: source,
      });
      saveBlob(file.blob, file.name);
      if (requestId === exportRequestId) exportStatus = get(LL).viewer.meeting.view.export_file_downloaded();
    } catch (error) {
      if (requestId === exportRequestId) exportStatus = error instanceof Error ? error.message : String(error);
    } finally {
      if (audioId === audioRequestId) audioExportBusy = false;
    }
  }

  function withSpeakerOverlay(
    transcript: TranscriptWordsV1 | null,
    overlay: SpeakerOverlay | null,
  ): TranscriptWordsV1 | null {
    if (!transcript || !overlay) return transcript;
    const { speakers, segments } = applySpeakerOverlay(transcript.speakers, transcript.segments, overlay);
    return { ...transcript, speakers: [...speakers], segments: [...segments] };
  }

  function mergeMeetingRuntimeSummary(
    entry: MeetingCatalogEntry,
    artifact: LoadedArtifact,
  ): MeetingCatalogEntry {
    return {
      ...entry,
      speakerCount: withoutSplitDevices(artifact.transcript.speakers).length,
      segmentCount: artifact.transcript.segments.length,
      digestDurationMs: artifact.transcript.media.durationMs,
    };
  }

  async function loadForMeeting(entry: MeetingCatalogEntry) {
    // Drop stale artifact synchronously so the view immediately shows a loading
    // state for *this* meeting rather than the previous meeting's transcript
    // bleeding through.
    resetLoadedArtifact();
    const request = artifactRequest;
    loading = true;
    errorMessage = "";
    pendingSeekMs = parseTimeHash(hostHash());
    resetTabs();
    try {
      const artifact = await dataProvider.loadMeetingForEntry(entry);
      if (request !== artifactRequest) return;
      applyArtifact(artifact);
      await maybeApplyUrlTranscript(entry);
      if (request !== artifactRequest) return;
      restoreSharedSelection();
      // Real speaker/segment/duration counts → shell updates the list card.
      dispatch("enriched", mergeMeetingRuntimeSummary(entry, artifact));
    } catch (error) {
      if (request !== artifactRequest) return;
      resetLoadedArtifact();
      loading = false;
      errorMessage = error instanceof Error ? error.message : String(error);
    } finally {
      if (request === artifactRequest) loading = false;
    }
  }

  // The operator republished this recording with its voices separated
  // differently, and what is on screen is the copy read before: read again on
  // its own when nothing is playing, or on "Voices updated · Reload".
  //
  // The meeting on screen stays until the new copy has arrived, rather than
  // blanking to a loading state for what is the same meeting with new voices,
  // and the reader keeps their place in it. Read on its own (`unlessPlaying`),
  // it is not put on screen if the reader started listening while it was being
  // read: a large recording takes a while, and the new copy replaces the
  // player. "Voices updated · Reload" is offered instead.
  let reloadingForSpeakers = false;
  async function reloadForSpeakers(unlessPlaying = false) {
    const entry = meeting;
    if (!entry || reloadingForSpeakers) {
      return;
    }
    reloadingForSpeakers = true;
    speakerSession.reloading(true);
    try {
      const artifact = await dataProvider.loadMeetingForEntry(entry, { fresh: true });
      if (meeting?.id !== entry.id || (unlessPlaying && playing)) {
        return;
      }
      // The republished file is at the same address, so the player would
      // keep the one it opened: its byte offsets moved with the speakers in
      // the file's header, and range requests against them would read the
      // wrong bytes. A new element opens the new file.
      const at = currentTimeMs;
      audioGeneration += 1;
      applyArtifact(artifact);
      if (at > 0) {
        // The new player takes the seek once it has read the file's header.
        pendingSeekMs = at;
        currentTimeMs = at;
      }
      dispatch("enriched", mergeMeetingRuntimeSummary(entry, artifact));
    } catch (error) {
      speakerSession.reportError(
        get(LL).viewer.meeting.view.reload_failed({ error: error instanceof Error ? error.message : String(error) }),
      );
    } finally {
      reloadingForSpeakers = false;
      speakerSession.reloading(false);
    }
  }

  async function loadBundled() {
    const request = ++artifactRequest;
    loading = true;
    errorMessage = "";
    pendingSeekMs = parseTimeHash(hostHash());
    resetTabs();
    try {
      const artifact = await dataProvider.loadBundledArtifact();
      if (request !== artifactRequest) return;
      applyArtifact(artifact);
      restoreSharedSelection();
    } catch (error) {
      if (request !== artifactRequest) return;
      errorMessage = error instanceof Error ? error.message : String(error);
    } finally {
      if (request === artifactRequest) loading = false;
    }
  }

  async function handleTranscriptSwitch(targetId: string) {
    if (
      transcriptSwitchPending ||
      !(meeting?.meetingPath ?? meeting?.audioPath) ||
      targetId === currentTranscriptId ||
      !availableTranscripts.some((entry) => entry.id === targetId)
    ) {
      return;
    }
    transcriptSwitchPending = true;
    transcriptSwitchError = "";
    try {
      const next = await dataProvider.switchTranscript(meeting, targetId);
      applySwitchedTranscript(next);
      writeTranscriptUrlParam(targetId);
      selectionRequest = null;
      lastSharedHash = hostHash();
    } catch (error) {
      // Surface inline next to the switcher; previous transcript stays visible.
      transcriptSwitchError = get(LL).viewer.meeting.view.switch_failed_detail({
        error: error instanceof Error ? error.message : String(error),
      });
    } finally {
      transcriptSwitchPending = false;
    }
  }

  function dismissTranscriptSwitchError() {
    transcriptSwitchError = "";
  }

  function writeTranscriptUrlParam(targetId: string) {
    if (!ownsHash) return;
    const current = currentViewerHash();
    const tx = targetId && targetId !== defaultTranscriptId ? targetId : "";
    window.history.replaceState(
      {},
      "",
      viewerHref(buildViewerHash({ meeting: current.meeting, tx })),
    );
  }

  function clearTranscriptUrlParam() {
    if (!ownsHash) return;
    const current = currentViewerHash();
    if (current.tx) {
      window.history.replaceState(
        {},
        "",
        viewerHref(buildViewerHash({ meeting: current.meeting, range: readViewerRange(hostHash()), timeMs: parseTimeHash(hostHash()) })),
      );
    }
  }

  async function maybeApplyUrlTranscript(entry: MeetingCatalogEntry) {
    const request = ++urlTranscriptRequest;
    const generation = artifactRequest;
    transcriptSwitchPending = false;
    let requested = currentViewerHash().tx || defaultTranscriptId;
    if (!requested || !(entry.meetingPath ?? entry.audioPath)) {
      return;
    }
    if (!availableTranscripts.some((descriptor) => descriptor.id === requested)) {
      clearTranscriptUrlParam();
      requested = defaultTranscriptId;
    }
    if (!requested || requested === currentTranscriptId) {
      return;
    }
    transcriptSwitchPending = true;
    try {
      const next = await dataProvider.switchTranscript(entry, requested);
      if (request !== urlTranscriptRequest || generation !== artifactRequest) return;
      // Navigation during the initial load is picked up here: the location
      // listener leaves that load responsible for applying the latest URL.
      if (requested !== (currentViewerHash().tx || defaultTranscriptId)) {
        await maybeApplyUrlTranscript(entry);
        return;
      }
      applySwitchedTranscript(next);
    } catch {
      if (request === urlTranscriptRequest && generation === artifactRequest) clearTranscriptUrlParam();
    } finally {
      if (request === urlTranscriptRequest) transcriptSwitchPending = false;
    }
  }

  /**
   * Read the playhead once. Deliberately does NOT schedule the next frame.
   *
   * It used to. Because it is also called from `handleTimeUpdate` (the media
   * element fires `timeupdate` about four times a second) and from `seekTo`,
   * every one of those calls started ANOTHER self-scheduling animation-frame
   * chain while one was already running, and `animationFrameId` kept only the
   * newest — so `stopPlaybackClock` could cancel exactly one of them and the
   * rest ran until playback stopped. Counted in the browser: 139 callbacks in
   * the first second of playback, 323 by the twelfth, and once the transcript
   * highlight stopped starving the frame budget, 2,644 — forty-four clocks
   * where there should be one, each re-reading `audioEl.currentTime` and
   * re-entering the reactive graph. Scheduling now belongs to the clock alone.
   */
  function syncPlaybackTime() {
    currentTimeMs = asFiniteMilliseconds(Math.round((audioEl?.currentTime ?? 0) * 1000));
    if (sampleStopMs !== null && currentTimeMs >= sampleStopMs) {
      stopSample();
    }
  }

  function playSample(id: string, startMs: number, endMs: number) {
    if (!audioEl) {
      return;
    }
    seekTo(startMs);
    sampleStopMs = endMs;
    playingSampleId = id;
    if (audioEl.paused) {
      void audioEl.play().catch(() => {
        stopSample();
        dispatch("playbackerror", get(LL).viewer.meeting.view.playback_failed());
      });
    }
  }

  function stopSample() {
    const wasSampling = sampleStopMs !== null;
    sampleStopMs = null;
    playingSampleId = null;
    if (wasSampling && audioEl && !audioEl.paused) {
      audioEl.pause();
    }
  }

  function advancePlaybackClock() {
    syncPlaybackTime();
    if (playing) {
      animationFrameId = window.requestAnimationFrame(advancePlaybackClock);
    }
  }

  function startPlaybackClock() {
    stopPlaybackClock();
    animationFrameId = window.requestAnimationFrame(advancePlaybackClock);
  }

  function stopPlaybackClock() {
    if (animationFrameId) {
      window.cancelAnimationFrame(animationFrameId);
      animationFrameId = 0;
    }
  }

  function handleLoadedMetadata() {
    syncDurationFromMedia();
    if (pendingSeekMs !== null) {
      // Completes a seek asked for before the media could take it, so it is
      // the same seek and keeps a sample that started it.
      seekAudio(pendingSeekMs);
      pendingSeekMs = null;
    }
  }

  function handleDurationChange() {
    syncDurationFromMedia();
  }

  function handlePlay() {
    playing = true;
    startPlaybackClock();
  }

  function handlePause() {
    sampleStopMs = null;
    playingSampleId = null;
    playing = false;
    stopPlaybackClock();
    syncPlaybackTime();
  }

  function handleTimeUpdate() {
    syncPlaybackTime();
  }

  function togglePlayback() {
    if (!audioEl) {
      return;
    }
    if (audioEl.paused) {
      void audioEl.play().catch(() => {
        dispatch("playbackerror", get(LL).viewer.meeting.view.playback_failed());
      });
      return;
    }
    audioEl.pause();
  }

  function seekTo(ms: number) {
    // Any seek, a sample's own included, ends the sample in progress;
    // playSample sets the next one after seeking.
    sampleStopMs = null;
    playingSampleId = null;
    seekAudio(ms);
  }

  function seekAudio(ms: number) {
    const nextTimeMs = Math.min(Math.max(0, ms), clampedDurationMs || ms);
    currentTimeMs = nextTimeMs;
    if (!audioEl) {
      pendingSeekMs = nextTimeMs;
      return;
    }
    if (audioEl.readyState === 0) {
      pendingSeekMs = nextTimeMs;
      audioEl.load();
      return;
    }
    audioEl.currentTime = nextTimeMs / 1000;
    syncPlaybackTime();
  }

  function handleTimelineInput(event: Event) {
    const target = event.currentTarget;
    if (!(target instanceof HTMLInputElement)) {
      return;
    }
    seekTo(Number(target.value));
  }

  function syncDurationFromMedia() {
    const reportedDurationMs = asFiniteMilliseconds(Math.round((audioEl?.duration ?? 0) * 1000));
    if (reportedDurationMs > 0) {
      durationMs = Math.max(durationMs, reportedDurationMs);
    }
  }

  function asFiniteMilliseconds(value: number): number {
    return Number.isFinite(value) ? value : 0;
  }

  function segmentDomId(segmentId: string): string {
    return `segment-${segmentId.replace(/[^A-Za-z0-9_-]/g, "_")}`;
  }

  async function scrollSegmentIntoView(segmentId: string, behavior: ScrollBehavior) {
    await tick();
    // In the embedded build the segment <article>s live inside the shadow root,
    // where document.getElementById can't reach them — resolve against the
    // component's root node (ShadowRoot embedded / Document standalone).
    const id = segmentDomId(segmentId);
    const root = viewRootEl?.getRootNode() as Document | ShadowRoot | undefined;
    const element = root?.getElementById?.(id) ?? document.getElementById(id);
    // As an embed, scroll only our own pane: scrollIntoView would also scroll
    // the page we are embedded in (D-838).
    if (surface === "embed") {
      if (element && scrollPaneEl) {
        const top = followScrollTop(
          scrollPaneEl.getBoundingClientRect(),
          element.getBoundingClientRect(),
          scrollPaneEl.scrollTop,
        );
        if (top !== null) scrollPaneEl.scrollTo({ top, behavior });
      }
      return;
    }
    element?.scrollIntoView({ behavior, block: "center" });
  }

  function handleAudioError() {
    dispatch("playbackerror", get(LL).viewer.meeting.view.playback_unsupported());
  }

  // Paused, the playhead is as often in a silence between turns as in one, and
  // then nothing is sounding; the turn it last passed the start of stands in.
  function rowKeyNear(ms: number): string | null {
    let key: string | null = transcriptRows[0]?.key ?? null;
    for (const row of transcriptRows) {
      if (row.startMs > ms) break;
      key = row.key;
    }
    return key;
  }

  function setOverlayHeight(height: number) {
    const delta = height - tabsHeight;
    tabsHeight = height;
    if (!delta || tabSwitching || !scrollPaneEl || scrollPaneEl.scrollTop <= 0) return;
    const pane = scrollPaneEl;
    void tick().then(() => {
      pane.scrollTop += delta;
    });
  }

  function revealSearch() {
    searchOpen = true;
    if (shownTab !== "transcript") void selectTab("transcript");
  }

  function jumpToTranscript() {
    if (shownTab !== "transcript") void selectTab("transcript");
  }

  async function toggleSearch() {
    if (searchExpanded) {
      searchOpen = false;
      transcriptQuery = "";
      searchToggleEl?.focus();
      return;
    }
    if (shownTab !== "transcript") await selectTab("transcript");
    searchOpen = true;
    await tick();
    searchSlot?.querySelector<HTMLInputElement>("input")?.focus();
  }

  function collapseSearchOnLeave(event: FocusEvent) {
    const next = event.relatedTarget;
    if (transcriptQuery.trim()) return;
    if (next instanceof Node && (searchSlot?.contains(next) || searchToggleEl?.contains(next))) return;
    searchOpen = false;
  }

  function resetTabs() {
    // A moment to seek to, or words carried in from a search, are both about
    // the transcript: open there, where they show.
    activeTab = pendingSeekMs === null && !initialQuery.trim() ? "summary" : "transcript";
    searchOpen = false;
    tabScrollTop = { summary: 0, transcript: 0 };
  }

  function trackHeight(node: HTMLElement, onHeight: (height: number) => void) {
    let report = onHeight;
    const measure = () => report(node.offsetHeight);
    const observer = new ResizeObserver(measure);
    observer.observe(node, { box: "border-box" });
    measure();
    return {
      update(next: (height: number) => void) {
        report = next;
        measure();
      },
      destroy() {
        observer.disconnect();
      },
    };
  }

  async function selectTab(tab: MeetingTab) {
    if (tab === shownTab) return;
    if (scrollPaneEl) tabScrollTop[shownTab] = scrollPaneEl.scrollTop;
    tabSwitching = true;
    activeTab = tab;
    await tick();
    if (overlayEl) tabsHeight = overlayEl.offsetHeight;
    if (tab === "transcript") {
      if (playerEl) playerHeight = playerEl.offsetHeight;
      await tick();
      transcriptFrame?.remeasure();
    }
    await tick();
    tabSwitching = false;
    if (scrollPaneEl) scrollPaneEl.scrollTop = tabScrollTop[tab];
    if (tab === "transcript" && followPlayback && !manualScrollLock) {
      const key = activeFollowRowKey ?? rowKeyNear(currentTimeMs);
      if (key) {
        lastAutoScrollRowKey = key;
        void scrollSegmentIntoView(key, "auto");
      }
    }
  }

  function handleTabKeydown(event: KeyboardEvent) {
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight" && event.key !== "Home" && event.key !== "End") return;
    event.preventDefault();
    const next: MeetingTab =
      event.key === "Home" ? "summary" : event.key === "End" ? "transcript" : shownTab === "summary" ? "transcript" : "summary";
    void selectTab(next);
    const list = (event.currentTarget as HTMLElement).closest('[role="tablist"]');
    list?.querySelector<HTMLElement>(`[data-tab="${next}"]`)?.focus();
  }

  function resumeFollow() {
    if (shownTab !== "transcript") {
      void selectTab("transcript");
    }
    followPlayback = true;
    manualScrollLock = false;
    const key = activeFollowRowKey ?? rowKeyNear(currentTimeMs);
    if (key) {
      lastAutoScrollRowKey = "";
      void scrollSegmentIntoView(key, "smooth");
    }
  }

  function toggleFollowPlayback() {
    if (followPlayback && manualScrollLock) {
      resumeFollow();
      return;
    }
    followPlayback = !followPlayback;
    // Turned back on, it goes to where the audio is now, not only once the
    // audio reaches its next turn: the reader may be anywhere by then.
    if (followPlayback) {
      resumeFollow();
    }
  }

  function handleWindowKeydown(event: KeyboardEvent) {
    if (event.code !== "Space" || event.repeat || event.defaultPrevented) {
      return;
    }
    // This is a WINDOW-level handler, so it stays live while the component is
    // merely hidden (display:none) rather than unmounted — e.g. under the app
    // shell's operator surface, where MeetingView keeps its state but is not
    // shown. A hidden section has no offsetParent; bail so Space stays free for
    // whatever surface is actually visible (button activation, scrolling) and we
    // never toggle the hidden player's audio.
    if (!viewRootEl || viewRootEl.offsetParent === null) {
      return;
    }
    // As an embed, Space is ours only when it was pressed inside the viewer;
    // everywhere else on the page it scrolls the page (D-838).
    if (surface === "embed" && !eventIsInside(event, viewRootEl)) {
      return;
    }
    if (keyboardEventTargetsControl(event)) {
      return;
    }
    event.preventDefault();
    togglePlayback();
  }

  // A row whose speaker just held the floor a moment ago does not repeat its
  // own name: the same rule as before, only asked of turns rather than of the
  // fragments a turn arrives in. A monologue the producer split at a two-second
  // pause is two turns, and the second one keeps its timestamp but drops the
  // duplicate header.
  function continuationRowKeys(rows: TranscriptRow<DisplaySegment>[]): Set<string> {
    const keys = new Set<string>();
    for (let index = 1; index < rows.length; index += 1) {
      const previous = rows[index - 1]!;
      const current = rows[index]!;
      if (!current.speaker || previous.speaker !== current.speaker) {
        continue;
      }
      if (current.startMs - previous.endMs <= CONTINUATION_GAP_MS) {
        keys.add(current.key);
      }
    }
    return keys;
  }

  /**
   * Re-derive the highlight, but only when the playhead has actually left the
   * stretch the last answer was good for.
   *
   * `resolvePlayhead` hands back the window its answer holds across, so the
   * common case — a frame landing between two word boundaries — costs one
   * comparison and returns without touching a single reactive source. Measured
   * on a transcript shaped like the largest published meeting, 36 of 480 frames
   * in an eight-second listen cross a boundary at all.
   *
   * The index is rebuilt when `displaySegments` changes, which is exactly when
   * its identity changes: that array is recomputed and never mutated, so the
   * identity test is both sound and complete.
   */
  // Which lines are sounding, recomputed only when the answer can have moved.
  function syncHighlight(segments: DisplaySegment[], timeMs: number): void {
    const rebuilt = playheadIndex.source !== segments;
    if (rebuilt) {
      playheadIndex = buildPlayheadIndex(segments);
    }
    if (
      !rebuilt &&
      timeMs >= highlightValidFromMs &&
      timeMs < highlightValidUntilMs
    ) {
      return;
    }

    const state = resolvePlayhead(playheadIndex, timeMs);
    highlightValidFromMs = state.validFromMs;
    highlightValidUntilMs = state.validUntilMs;

    activeSegments = state.soundingBlocks as DisplaySegment[];
    activeSegmentIds = new Set(activeSegments.map((segment) => segment.id));
  }

  function syncWordHighlight(partsByBlock: Map<string, TranscriptWordPart[]>, timeMs: number, soundingBlockIds: Set<string>): void {
    if (wordHighlightSource !== partsByBlock) {
      wordHighlightSource = partsByBlock;
      wordHighlighter.setWords([...partsByBlock].flatMap(([blockId, parts]) =>
        parts.flatMap((part, order) => part.startMs !== undefined && part.endMs !== undefined
          ? [{ id: part.id, startMs: part.startMs, endMs: part.endMs, blockId, order,
              ambiguous: part.alignment === "interpolated" || part.sourceWordsRejected }]
          : []),
      ));
    }
    // Seeking is allowed for display tokens with rejected source references;
    // playback must still respect D-690's independent acoustic eligibility.
    wordHighlighter.update(timeMs, soundingBlockIds);
  }

  // The blocks a row renders as its own speaker's prose — the turn's own
  // fragments, not the chips nested in it. What rings when the turn is
  // sounding, and what the crosstalk warning is judged on.
  function rowSpeechBlocks(row: TranscriptRow<DisplaySegment>): DisplaySegment[] {
    return row.members
      .filter((member): member is Extract<typeof member, { kind: "speech" }> => member.kind === "speech")
      .map((member) => member.block);
  }

  // The ring says "this speaker is sounding now". It is judged on the turn's
  // OWN blocks: a backchannel inside the turn is sounding on its own account
  // and lights its own chip, and must not claim the host was still talking.
  function isRowSounding(row: TranscriptRow<DisplaySegment>, sounding: Set<string>): boolean {
    return rowSpeechBlocks(row).some((block) => sounding.has(block.id));
  }

  function isRowLikelyCrosstalk(row: TranscriptRow<DisplaySegment>): boolean {
    return isLikelyCrosstalkAcrossBlocks(rowSpeechBlocks(row));
  }

  function likelyCrosstalkTitle(speakerLabel: string): string {
    return get(LL).viewer.meeting.transcript.crosstalk_title({ name: shownSpeakerLabel(speakerLabel) });
  }

  // "over Chris", "over Chris and Dana" - names, never durations. The measured
  // simultaneity stays in the model; a reader can act on who, not on how long.
  function formatSpeakerList(labels: readonly string[]): string {
    return formatNameList(labels);
  }

  // The switcher's name for a transcript: the two a separated meeting has are
  // named in the reader's language; any other keeps its humanized id.
  function transcriptLabel(descriptor: PortableTranscriptDescriptor): string {
    if (descriptor.id === "separated-voices") return $LL.viewer.meeting.load.transcript_separated();
    if (descriptor.id === "raw-asr") return $LL.viewer.meeting.load.transcript_original();
    return descriptor.label;
  }






  onMount(() => {
    window.addEventListener("keydown", handleWindowKeydown);
    window.addEventListener("hashchange", handleSharedLocation);
    window.addEventListener("popstate", handleSharedLocation);
    if (bundled) {
      void loadBundled();
    }
  });

  onDestroy(() => {
    artifactRequest += 1;
    urlTranscriptRequest += 1;
    locationRequest += 1;
    window.removeEventListener("keydown", handleWindowKeydown);
    window.removeEventListener("hashchange", handleSharedLocation);
    window.removeEventListener("popstate", handleSharedLocation);
    stopPlaybackClock();
    void localMarks.close();
  });

  // Reactive `bundled`: the shell can flip this at any time — an embedded
  // viewer that fell back to the bundled artifact and then recovered its
  // catalog is exactly that transition. Without a handler here, a failed
  // bundled load left errorMessage set and NEITHER branch below could clear it
  // (the first needs a meeting, the second needs a non-null attemptedKey, and a
  // bundled load sets neither) — so the "Meeting not found" card survived the
  // recovery and stayed on screen until the user clicked something (D-543).
  //
  // This lives in the component rather than only in the shell because
  // MeetingView is a published entry point ("./MeetingView.svelte") — any host
  // that toggles `bundled` reproduces the same stuck card.
  $: if (bundled !== lastBundled) {
    const wasBundled = lastBundled;
    lastBundled = bundled;
    if (bundled) {
      void loadBundled();
    } else if (wasBundled) {
      resetLoadedArtifact();
      errorMessage = "";
    }
  }

  // Reactive load: when the shell selects a different meeting, load it. Guarded
  // by attemptedKey so catalog enrichment (which changes the meeting object
  // identity but not its id) and load failures do not retrigger. Deselecting
  // (meeting → null) clears the loaded artifact.
  $: if (!bundled && meeting && meeting.id !== attemptedKey) {
    attemptedKey = meeting.id;
    void loadForMeeting(meeting);
  } else if (!bundled && !meeting && attemptedKey !== null) {
    attemptedKey = null;
    resetLoadedArtifact();
    errorMessage = "";
  }

  $: marksFor = loadAnnotations ? (meeting?.id ?? "") : null;
  $: if (!marksSession && marksFor !== openedMarksFor) {
    openedMarksFor = marksFor;
    void marks.open(loadAnnotations, applyAnnotations);
  }

  $: summaryHtml = renderSummaryHtml(summaryMarkdown);
  // Reading order, then EFFECTIVE timings, then overlap. The order matters:
  // the producer appends wordless segments last so the array cannot be trusted
  // to be sorted, and the overlap analysis has to see repaired spans or it
  // spends most of its time labelling decoder-fabricated silence as crosstalk
  // (D-690). repairTurnFinalWordInflation copies rather than mutates, so the
  // loaded artifact keeps its canonical times and every word keeps its original
  // START — seek targets never move.
  let transcriptQuery = "";
  let onlyMatching = false;
  // Seeded from a cross-meeting search result (D-736): opening a moment from
  // the list carries the query in, so the meeting lands already filtered to the
  // lines that matched rather than making the reader retype it.
  //
  // Applied per meeting rather than reactively on the value, so that clearing
  // or editing the box stays the reader's own — a plain `$:` assignment here
  // would fight every keystroke by resetting to the incoming prop.
  export let initialQuery = "";
  let seededQueryFor = "";
  $: if (meeting && seededQueryFor !== meeting.id) {
    seededQueryFor = meeting.id;
    transcriptQuery = initialQuery;
  }

  $: derivedSegments = transcriptIndex
    ? displaySegmentsForArtifact({
        index: transcriptIndex,
        readableTranscript,
        displayTranscript,
        wordEndsBoundedByAudio,
      })
    : [];
  // Names and "same person" merges saved since this copy of the recording was
  // published are shown on it at once: on its turns, in Copy and Download, in
  // the People panel and the header. The operator writes them into the
  // default transcript only, so another transcript is shown as it is. Keyed
  // by a string so the transcript is recomputed when the overlay changes, not
  // at every answer from the operator.
  $: shownOverlayKey = speakerOverlayKey(speakerOverlayFor($speakerSession));
  $: speakerOverlay = speakerOverlayFromKey(shownOverlayKey);
  $: displaySegments = applySpeakerOverlay(
    transcriptIndex?.transcript.speakers ?? [],
    derivedSegments,
    currentTranscriptId === defaultTranscriptId ? speakerOverlay : null,
  ).segments as DisplaySegment[];
  // The seam this was always for. The filter lives in core/transcript.ts
  // because the interesting half is the mapping from matched canonical segments
  // to rendered blocks, and that deserves a test that does not need a DOM.
  // Hiding what does not match is opt-in; find itself only highlights.
  $: visibleSegments = onlyMatching
    ? filterDisplaySegmentsByQuery(transcriptIndex, displaySegments, transcriptQuery)
    : displaySegments;
  // Rows are TURNS, not blocks: the producer flushes a segment at every speaker
  // change, so one sentence spoken over somebody else arrives as a dozen
  // fragments and only the turn they came from is worth reading (D-693).
  $: transcriptRows = buildTranscriptRows(visibleSegments);
  // Keyed by block id and built from EVERY block, not the filtered ones: it is
  // a lookup, so covering blocks that are currently hidden costs a few map
  // entries, while missing one a row still renders would drop its words (D-734).
  $: wordPartsByBlock = new Map(displaySegments.map((block) => [block.id, transcriptWordParts(block)]));
  $: timedWords = wordsByTime([...wordPartsByBlock.values()].flat());
  $: findStopList = findStops(transcriptIndex, transcriptRows, wordPartsByBlock, transcriptQuery);
  $: activeFollowRowKey = followRowKeyForBlocks(transcriptRows, activeSegments);
  $: continuationKeys = continuationRowKeys(transcriptRows);
  // Highlight membership runs on the same effective audible spans the overlap
  // analysis judges on, not on paragraph extents: extents ring both speakers
  // (and follow-scroll the earlier paragraph) through stretches where their
  // words strictly alternate. Wordless blocks keep their extent.
  //
  // PUSHED ON A BOUNDARY, NOT DERIVED ON A FRAME (D-692). These five were `$:`
  // over `currentTimeMs`, so each of the sixty playhead writes a second rebuilt
  // them — and because two of them are a fresh Map and a fresh Set, and legacy
  // reactivity compares objects by identity, every consumer of the playhead was
  // invalidated each time. On the largest published meeting that is 7,318
  // word-button effects marked, scheduled and dirty-checked sixty times a
  // second to discover that one or two of them changed; the profile was
  // accordingly 93% busy, four fifths of it Svelte bookkeeping. `syncHighlight`
  // keeps them assigned only when the answer actually moves — which, since a
  // word lasts a few hundred milliseconds, is a few times a second rather than
  // sixty. The work is not made cheaper; it is not entered.
  $: syncHighlight(displaySegments, currentTimeMs);
  $: syncWordHighlight(wordPartsByBlock, currentTimeMs, activeSegmentIds);
  $: hasPrecomputedDisplay = displayTranscript !== null;
  $: safeDurationMs = asFiniteMilliseconds(durationMs);
  $: clampedDurationMs = Math.max(0, safeDurationMs);
  $: clampedCurrentTimeMs = Math.min(Math.max(0, asFiniteMilliseconds(currentTimeMs)), clampedDurationMs || 0);
  $: remainingMs = Math.max(0, clampedDurationMs - clampedCurrentTimeMs);
  $: participants = $speakerSession.server?.participants ?? [];
  // The People panel lists the meeting's people: every device, with the
  // voices separated from a shared one beneath it, whichever transcript is
  // shown, so they can be named and listened to from either.
  $: peopleTranscript = withSpeakerOverlay(openedTranscript ?? transcriptIndex?.transcript ?? null, speakerOverlay);
  $: speakerGroups = groupSpeakers(withoutSplitDevices(peopleTranscript?.speakers ?? []), participants, splitDevices);
  $: speakerSamples = speakerEditsOffered && peopleTranscript ? voiceSamples(peopleTranscript) : new Map();
  // A recording separated differently from the one the operator published,
  // or with another summary, is read again, once per apply, unless the
  // reader is listening: a reload replaces the player, so then "Voices
  // updated · Reload" waits for them.
  $: speakersReloadDue = reloadDue(
    $speakerSession,
    new Set((openedTranscript?.speakers ?? []).map((speaker) => speaker.id)),
  );
  let autoReloadedFor = "";
  $: if (speakersReloadDue && meeting) {
    const key = `${meeting.id}:${$speakerSession.server?.appliedRevision}`;
    if (key !== autoReloadedFor) {
      autoReloadedFor = key;
      if (!playing) void reloadForSpeakers(true);
    }
  }
  $: hasSummaryTab = Boolean(summaryHtml) || linkedInsights.length > 0;
  // A meeting with no summary says why, when its file says, and offers to
  // write one where the operator can (D-814). A meeting with no transcript
  // has its own message in the transcript, and nothing to summarize.
  $: summaryReasonText = summaryHtml ? null : missingSummaryText(summaryStatus);
  $: transcribedForSummary = !transcriptionStatus || transcriptionStatus.status === "completed";
  $: writeSummaryShown =
    !summaryHtml &&
    transcribedForSummary &&
    ((summaryRequest !== null && (summaryRequest.canWrite || summaryRequest.state !== "idle")) || summaryReasonText !== null);
  $: regenerateSummaryShown =
    Boolean(summaryHtml) && summaryRequest !== null && (summaryRequest.canRegenerate || summaryRequest.state !== "idle");
  $: shownTab = hasSummaryTab ? activeTab : ("transcript" as MeetingTab);
  $: overlayShown = Boolean(transcriptIndex) && (hasSummaryTab || displaySegments.length > 0);
  $: tabsOffset = overlayShown ? tabsHeight : 0;
  $: searchShown = searchOpen || transcriptQuery.trim() !== "" || !hasSummaryTab;
  $: searchExpanded = searchShown;
  $: void searchExpanded, void tick().then(() => {
    if (overlayEl) setOverlayHeight(overlayEl.offsetHeight);
  });
  $: if (
    shownTab === "transcript" &&
    followPlayback &&
    !manualScrollLock &&
    activeFollowRowKey &&
    activeFollowRowKey !== lastAutoScrollRowKey
  ) {
    lastAutoScrollRowKey = activeFollowRowKey;
    void scrollSegmentIntoView(activeFollowRowKey, "smooth");
  }
</script>

